module.exports = function(RED) {
    "use strict";

    var mqtt = require("mqtt");
    var Readable = require("stream").Readable;
    var topics = require("./lib/meo-topics");

    var DEVICE_LIST_TIMEOUT = 5000;
    // The edge waits up to 10s for the device's reply; leave room on top.
    var COMMAND_TIMEOUT = 15000;
    // Device frames are QoS 0 on /up.
    var SUBSCRIBE_QOS = 0;
    // 4-byte frame: type(3b)|seq(5b), idx, int16 LE. Mirrors define/MeoMsgFrame.java.
    var FRAME_SIZE = 4;
    var TYPE_EVENT = 4;
    // The edge image ships the broker alongside Node-RED and the service, so
    // the broker address is not configurable — it is always the edge's, on
    // the MQTT default port (matching the service's MEO_MQTT_BROKER default).
    var BROKER_PORT = 1883;

    var STATUS = {
        connecting: { fill: "yellow", shape: "ring", text: "node-red:common.status.connecting" },
        connected: { fill: "green", shape: "dot", text: "node-red:common.status.connected" },
        disconnected: { fill: "red", shape: "ring", text: "node-red:common.status.disconnected" }
    };

    // Edge errorCode → message key. Mirrors define/MeoErr.java.
    var ERROR_KEYS = {
        1: "meo.errors.badRequest",
        2: "meo.errors.capNotSupported",
        3: "meo.errors.handleFailed",
        4: "meo.errors.opNotSupported",
        110: "meo.errors.deviceNotFound",
        120: "meo.errors.noReply",
        121: "meo.errors.sendFailed"
    };

    function fetchDevices(apiUrl) {
        return fetch(apiUrl + "/api/v1/devices", {
            signal: AbortSignal.timeout(DEVICE_LIST_TIMEOUT)
        }).then(function(response) {
            if (!response.ok) {
                throw new Error("edge returned " + response.status);
            }
            return response.json();
        });
    }

    function MeoEdgeNode(n) {
        RED.nodes.createNode(this, n);
        var node = this;
        node.name = n.name;
        node.host = n.host || "localhost";
        node.port = Number(n.port) || 7070;

        node.apiUrl = function() {
            return "http://" + node.host + ":" + node.port;
        };

        node.brokerUrl = function() {
            return "mqtt://" + node.host + ":" + BROKER_PORT;
        };

        // ── Commands ──────────────────────────────────────────────────────
        // Sent through the edge's HTTP API, not MQTT: the edge owns the
        // per-device seq counter, and a second publisher would collide with it.

        // Resolves with the value the device reports.
        node.sendCommand = function(deviceId, cap, op, value) {
            return fetch(node.apiUrl() + "/api/v1/devices/" + encodeURIComponent(deviceId) + "/command", {
                method: "POST",
                headers: { "content-type": "application/json" },
                body: JSON.stringify({ cap: cap, op: op, value: value }),
                signal: AbortSignal.timeout(COMMAND_TIMEOUT)
            }).catch(function(err) {
                throw new Error(RED._(err.name === "TimeoutError" ? "meo.errors.noReply" : "meo.errors.notConnected"));
            }).then(function(response) {
                return response.json().catch(function() { return {}; }).then(function(body) {
                    if (response.ok) { return body.value; }
                    var key = ERROR_KEYS[body.errorCode];
                    throw new Error(key ? RED._(key) : (body.error || RED._("meo.errors.deviceError", { error: response.status })));
                });
            });
        };

        // ── Events ────────────────────────────────────────────────────────
        // One connection per edge shared by every event node: connect on the
        // first, disconnect on the last.

        var listeners = {};
        var client = null;
        // deviceId → cap keys; array index is the cap's idx on the wire.
        var capsByDevice = {};
        var capsFetch = null;

        node.registerListener = function(listener) {
            var first = Object.keys(listeners).length === 0;
            listeners[listener.id] = listener;
            if (first) {
                connect();
            }
            // Deferred: a status set mid-construction does not reach the editor.
            setTimeout(function() {
                if (listeners[listener.id]) { setStatus(listener); }
            }, 0);
        };

        node.deregisterListener = function(listener, done) {
            delete listeners[listener.id];
            if (Object.keys(listeners).length === 0) {
                disconnect(done);
                return;
            }
            done();
        };

        // One fetch in flight at a time, however many events miss the cache.
        // ponytail: refreshed only on an unknown device/idx and on reconnect, so a
        // re-provision that keeps the cap count mislabels until then.
        function refreshCaps() {
            if (!capsFetch) {
                capsFetch = fetchDevices(node.apiUrl()).then(function(devices) {
                    capsByDevice = {};
                    (devices || []).forEach(function(device) {
                        capsByDevice[device.deviceId] = device.caps || [];
                    });
                }).catch(function(err) {
                    node.warn(RED._("meo.errors.capsFailed", { message: err.message }));
                }).then(function() {
                    capsFetch = null;
                });
            }
            return capsFetch;
        }

        function connect() {
            client = mqtt.connect(node.brokerUrl(), {
                clientId: "meo-nodered-" + RED.util.generateId(),
                reconnectPeriod: RED.settings.mqttReconnectTime || 5000,
                clean: true
            });
            client.on("connect", function() {
                refreshCaps();
                // Re-subscribes on every reconnect: clean session, so the broker
                // keeps nothing for us across a drop.
                client.subscribe(topics.UP_WILDCARD, { qos: SUBSCRIBE_QOS }, function(err) {
                    if (err) {
                        node.error(RED._("meo.errors.subscribeFailed",
                            { topic: topics.UP_WILDCARD, message: err.message }));
                        return;
                    }
                    node.log(RED._("meo.events.subscribed",
                        { topic: topics.UP_WILDCARD, broker: node.brokerUrl() }));
                    broadcastStatus();
                });
            });
            client.on("reconnect", broadcastStatus);
            client.on("close", broadcastStatus);
            client.on("error", function(err) {
                node.error(err.message || RED._("meo.errors.brokerError"));
            });
            client.on("message", onMessage);
        }

        function disconnect(done) {
            if (!client) {
                done();
                return;
            }
            var ending = client;
            client = null;
            // Forced: nothing of ours is in flight, and an unreachable broker
            // must not stall a deploy.
            ending.end(true, {}, done);
        }

        // /up also carries OK/ERR replies to the edge's commands; only EVENT is ours.
        function onMessage(topic, payload) {
            var deviceId = topics.deviceIdFromTopic(topic);
            if (deviceId === null || !Buffer.isBuffer(payload) || payload.length !== FRAME_SIZE) {
                return;
            }
            if ((payload.readUInt8(0) >> 5) !== TYPE_EVENT) {
                return;
            }
            var idx = payload.readUInt8(1);
            var value = payload.readInt16LE(2);
            var keys = capsByDevice[deviceId];
            if (keys && idx < keys.length) {
                dispatch(deviceId, keys[idx], value);
                return;
            }
            refreshCaps().then(function() {
                var fresh = capsByDevice[deviceId];
                if (fresh && idx < fresh.length) {
                    dispatch(deviceId, fresh[idx], value);
                } else {
                    node.debug("dropping event for unknown cap idx " + idx + " on " + topic);
                }
            });
        }

        function dispatch(deviceId, cap, value) {
            Object.keys(listeners).forEach(function(id) {
                listeners[id].onDeviceEvent(deviceId, cap, value);
            });
        }

        function setStatus(listener) {
            listener.status(client && client.connected ? STATUS.connected : STATUS.connecting);
        }

        function broadcastStatus() {
            var status = client && client.connected ? STATUS.connected : STATUS.disconnected;
            Object.keys(listeners).forEach(function(id) {
                listeners[id].status(status);
            });
        }

        node.on("close", function(done) {
            listeners = {};
            disconnect(done);
        });
    }
    RED.nodes.registerType("meo-edge", MeoEdgeNode);

    // ── Editor support ────────────────────────────────────────────────
    // The edit dialogs go through here rather than calling the edge from
    // the browser: the runtime shares a host with the edge, the browser
    // may not (open the editor from a laptop and "localhost" is the laptop).

    // Host/port come from the query, not from a deployed config node, so the
    // device list works while the edge node is still being filled in.
    RED.httpAdmin.get("/meo/devices", RED.auth.needsPermission("meo-edge.read"), function(req, res) {
        var host = req.query.host;
        var port = Number(req.query.port);
        if (!/^[A-Za-z0-9._-]+$/.test(host || "")) {
            res.status(400).json({ message: "invalid edge host" });
            return;
        }
        if (!(port > 0 && port < 65536)) {
            res.status(400).json({ message: "invalid edge port" });
            return;
        }
        fetchDevices("http://" + host + ":" + port).then(function(devices) {
            res.json(devices || []);
        }).catch(function(err) {
            // Unreachable edge is the common case here, not a server fault.
            res.status(502).json({ message: err.message || "edge unreachable" });
        });
    });

    // ── Sidebar proxy ─────────────────────────────────────────────────
    // The MEO sidebar reaches the service through here for the same reason the
    // dialogs do. Unlike /meo/devices above there is no host to pass: the
    // sidebar manages *this* edge, which is always the machine the runtime
    // runs on.
    var SERVICE_URL = (process.env.MEO_API_URL || "http://localhost:7070").replace(/\/+$/, "");
    // The service's scan blocks for DEFAULT_SCAN_TIMEOUT_MS (8s), so this ceiling
    // has to clear it with room to spare.
    var PROXY_TIMEOUT = 30000;

    function proxyPermission(req, res, next) {
        RED.auth.needsPermission(req.method === "GET" ? "meo-edge.read" : "meo-edge.write")(req, res, next);
    }

    // Registered before the catch-all: SSE has to stream, not buffer.
    // EventSource cannot send an auth header, so with adminAuth enabled this
    // route would 401 — the shipped edge sets no adminAuth.
    // ponytail: query-param token if that ever changes.
    RED.httpAdmin.get("/meo/api/provision/events", function(req, res) {
        var upstream = new AbortController();
        req.on("close", function() { upstream.abort(); });
        fetch(SERVICE_URL + "/api/v1/provision/events", {
            headers: { accept: "text/event-stream" },
            signal: upstream.signal
        }).then(function(response) {
            if (!response.ok || !response.body) {
                throw new Error("service returned " + response.status);
            }
            // no-transform keeps compression middleware from holding events back.
            res.writeHead(200, {
                "content-type": "text/event-stream",
                "cache-control": "no-cache, no-transform",
                "connection": "keep-alive"
            });
            res.flushHeaders();
            Readable.fromWeb(response.body)
                .on("error", function() { res.end(); })
                .pipe(res);
        }).catch(function(err) {
            if (!res.headersSent) {
                res.status(502).json({ message: err.message || "service unreachable" });
            } else {
                res.end();
            }
        });
    });

    RED.httpAdmin.all("/meo/api/*", proxyPermission, function(req, res) {
        var query = req.originalUrl.indexOf("?");
        var url = SERVICE_URL + "/api/v1/" + req.params[0] +
                  (query === -1 ? "" : req.originalUrl.slice(query));
        // adminApp parses JSON bodies before we see them, so re-serialize rather
        // than piping the (already consumed) request stream.
        var body = req.body && Object.keys(req.body).length > 0 ? JSON.stringify(req.body) : undefined;
        fetch(url, {
            method: req.method,
            headers: body ? { "content-type": "application/json" } : undefined,
            body: body,
            signal: AbortSignal.timeout(PROXY_TIMEOUT)
        }).then(function(response) {
            return response.text().then(function(text) {
                res.status(response.status);
                var type = response.headers.get("content-type");
                if (type) { res.set("content-type", type); }
                res.send(text);
            });
        }).catch(function(err) {
            res.status(502).json({ message: err.message || "service unreachable" });
        });
    });
};
